INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1431430-mis399', 'stk-user8581', 'MIS 399', 'info', '{"desc": "التدريب الصيفي/التعاوني (تجارب-نصائح- شركات) موضوع يهم الجميع بلا استثناء\n\nتجربة العضو 😦http://stkfupm.com/forum/member.php?u=2361)\n(http://stkfupm.com/forum/member.php?u=2361)\nMIS Student\n\n*اسم الشركة اللي تدربت فيها؟\n\nالشركة الوطنية لصناعة البسكويت والحلويات (تيشوب والبطل) سنة 2008\n\n*هل تدربت على الشي اللي درسته؟\nلا كان عملي في ادارة المشتريات لكن ما كنت اسوي شي بسبب ان عملهم روتيني جدا وكله طلبيات وكل شخص مسؤول عن شغله … اشتغلت بس اشياء بسيطة\n\n*هل استمتعت في التدريب او ممل او متعب؟\nممل جدا\n\n*كيف تقيمك للتدريب بشكل عام ؟\nانا استغليت وقتي بالشغل على الريبورت وكانت التجربة عادية\n\n*ماهي ابرز الصعوبات اللي واجهتك؟\nما في صعوبات\n\n*نصائح او توجيهات او اقتراحات للي مقلبين ع التدريب ؟\nغالبا لا تتوقع انك بتحصل شركة مثالية الا ما ندر … نسبة كبيرة منهم تروح عندهم وتتسدح ولا تسوي شي ولا تتوقع ان اللي درسته بتقدر تطبقه على ارض الواقع ولكن في الاخير يعتمد عليك وعلى مدى قدرتك على ربط العمل بما درسته سابقا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/4", "user": "user8581", "ts": 1446062896000, "tid": 170460, "pn": 4}}', 1446062896000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1322679-mis399', 'stk-taha_khaled', 'MIS 399', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nأفدم لكم قائمة افضل شركات البترول والغاز في السعودية والتي يكون فيها التوظيف مفتوح\n\nعلى مدار العام\n\nوتطلب التخصصات التالية :-\n\n1- كلية الهندسة * يمكنك التدرب فيها من خلال التدريب الصيفي\n\n2- كلية علوم الارض * يمكنك التدرب فيها من خلال التدريب الصيفي\n\n3- كلية الحاسبات ( cs و it ) * يمكنك التدرب فيها من خلال التدريب الصيفي\n\n4- كلية الاقتصاد والادارة ( المحاسبة ، الموارد البشرية ، نظم المعلومات الادارية )\n\n5- كلية العلوم ( الفيزياء - والكيمياء ) * بعض الشركات تطلبها وليست كلها\n\n* من خلال بحثي وجدت ان هده التخصصات هي المطلوبة لدى شركات البترول والغاز\n\nقائمة الشركات :-\n\n- شركة ارامكو\n\n- شركة شلمبرجير\n\n- شركة بيكرهيوز\n\n- شركة هاليبرتون\n\n- شركة وذرفورد\n\n- شركة شيفرون\n\n- شركة بكتل\n\n- شركة اركاس\n\n- شركة مكامن\n\n- شركة الحوطي\n\n- شركة الحفر العربية\n\n- شركة اكسون موبيل\n\n- شركة الزيت العربية السعودية\n\n- شركة فلور\n\n- بترو رابغ\n\n- الجبيل الصناعية\n\n- ينبع الصناعية\n\nوهناك غيرها الكثير من الشركات وهدي افضلها\n\nتتميز هذه الشركات بقوة الراتب + البدلات\n\nفي الختام تقبلو مني خالص تحياتي\n\nمنقول من منتديات طلاب وطالبات جامعة الملك عبدالعزيز", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/155834/1", "user": "taha_khaled", "ts": 1390762965000, "tid": 155834, "pn": 1}}', 1390762965000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
